// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface IcdStatisticsOut {
  date_from: string;
  date_to: string;
  /** How many records of each kind carry a code (MSDS 105 vii) */
  completeness: IcdCompletenessOut[];
  chapters: IcdChapterCountOut[];
  top_codes: IcdCodeCountOut[];
  /** The ICD-11 attribution to print on the report (null when only ICD-10 was used) */
  citation: string | null;
}

export interface IcdCompletenessOut {
  source: "OPD" | "Inpatient" | "Deaths";
  /** Finalized OPD / emergency notes; patients discharged; deaths certified */
  records: number;
  coded: number;
  coded_pct: number | null;
}

export interface IcdChapterCountOut {
  /** Null only for a code of unknown format (should not happen) */
  code_system: "ICD-11" | "ICD-10" | null;
  /** Null: the code is in no loaded list */
  chapter: string | null;
  title: string | null;
  opd: number;
  inpatient: number;
  deaths: number;
  total: number;
}

export interface IcdCodeCountOut {
  code: string;
  code_system: "ICD-11" | "ICD-10" | null;
  title: string | null;
  uri: string | null;
  opd: number;
  inpatient: number;
  deaths: number;
  total: number;
}

export interface IcdReleasesOut {
  /** The classification doctors code in (setting icd_coding_system) */
  coding_system: "ICD-11" | "ICD-10";
  releases: IcdReleaseOut[];
  /** The attribution the ICD-11 licence requires on screens and reports that use it */
  icd11_citation: string;
}

export interface IcdReleaseOut {
  release_id: number;
  code_system: "ICD-11" | "ICD-10";
  /** e.g. "2026-01" (ICD-11) or "2019" (ICD-10) */
  release_label: string;
  language: string;
  /** Bundled: shipped with the product (ICD-11); Imported: loaded by the hospital (its licensed ICD-10, or a newer ICD-11) */
  source: "Bundled" | "Imported";
  source_file: string | null;
  source_sha256: string | null;
  /** The licence the list is used under; show it where the list is used */
  licence_note: string;
  /** Codable categories */
  code_count: number;
  /** The list the picker searches and new codes are checked against */
  is_active: boolean;
  loaded_by: number | null;
  loaded_by_name: string | null;
  loaded_at: string;
  row_version: number;
}

/** Coded diagnosis statistics: by ICD chapter and code, and coding completeness — GET /api/v1/icd/statistics (who may call: holders of icd.statistics.view). */
export function codedStatistics(query?: { date_from?: string | null; date_to?: string | null; limit?: number }): Promise<IcdStatisticsOut> {
  return api<IcdStatisticsOut>("GET", withQuery(`/icd/statistics`, query), undefined);
}

/** The ICD code lists loaded — GET /api/v1/icd/releases (who may call: any logged-in user). */
export function releases(): Promise<IcdReleasesOut> {
  return api<IcdReleasesOut>("GET", `/icd/releases`, undefined);
}
